// (L308); "Die Ziffern in Klammern geben an, in wie viel Prozent der Proben die Werte eingehalten sein müssen." (L309).
// A printed "-" is seeded as null. The Darmviren volume prints "10 1*)" (L305) — the unit glyph is ambiguous
// (OCR "l" vs "1"): volume_ml is null, the printed text is kept (m205-U-1) and the table stays imported_unverified.
// ---------------------------------------------------------------------------
export const TAB1_PARAMETER = [
  { value: 'gesamtcoliforme', label_de: 'Gesamtcoliforme Bakterien in 100 ml', g: 500, g_pct: 80, i: 10000, i_pct: 95, volume_ml: 100, volume_text: '100 ml', anforderung: false, cells: ['500 (80)', '10.000 (95)'], q: 'T1_L301' },
  { value: 'faekalcoliforme', label_de: 'Fäkalcoliforme Bakterien in 100 ml', g: 100, g_pct: 80, i: 2000, i_pct: 95, volume_ml: 100, volume_text: '100 ml', anforderung: false, cells: ['100 (80)', '2.000 (95)'], q: 'T1_L302' },
  { value: 'strep_faecalis', label_de: 'Streptococcus faecalis in 100 ml *)', g: 100, g_pct: 90, i: null, i_pct: null, volume_ml: 100, volume_text: '100 ml', anforderung: true, cells: ['100 (90)', '& - '], q: 'T1_L303' },
  { value: 'salmonellen', label_de: 'Salmonellen in 1000 ml *)', g: null, g_pct: null, i: 0, i_pct: 95, volume_ml: 1000, volume_text: '1000 ml', anforderung: true, cells: ['& - ', '0 (95)'], q: 'T1_L304' },
  { value: 'darmviren', label_de: 'Darmviren in 10 l *)', g: null, g_pct: null, i: 0, i_pct: 95, volume_ml: null, volume_text: '10 1', anforderung: true, cells: ['& - ', '0 (95)', '10 1*)'], q: 'T1_L305' },
] as const;
export function tabelle1AsTable(): RegulationTable {
  const rows: RegulationRow[] = TAB1_PARAMETER.map((r, i) => {
    const quote = Q[r.q];
    for (const c of r.cells) inSpan(quote, c, `TABELLE1 ${r.value}`);
    return { row_key: r.value, keys: { parameter: r.value }, group_label: null, label_de: r.label_de, order_index: i,
      values: { g_wert: r.g, g_pct: r.g_pct, i_wert: r.i, i_pct: r.i_pct, volume_ml: r.volume_ml, volume_text: r.volume_text, auf_anforderung: r.anforderung }, verbatim_quote: quote };
  });
  return { standard_code: STD, edition: ED, table_code: 'TABELLE1', title_de: 'Mikrobiologische Qualitätsanforderungen an Badegewässer nach der Richtlinie 76/160/EWG (Leitwert G / Grenzwert I, Perzentil in Klammern)', clause_reference: '§3.2, Tab. 1', page_ref: null,
    key_columns: ['parameter'],
    value_columns: [num('g_wert'), num('g_pct', '%'), num('i_wert'), num('i_pct', '%'), num('volume_ml', 'ml'), str('volume_text'), { name: 'auf_anforderung', type: 'boolean' }],
    override_policy: 'anhaltswert',
    override_quote: Q.L232, // §2.1 "Die Festlegung des Behandlungsziels für die Abwasserdesinfektion erfolgt in der Regel durch die zuständige Behörde. …"
    verification_status: 'imported_unverified', rows };
}

// ---------------------------------------------------------------------------
// Tabelle 2 — Mikrobiologische Qualitätsanforderungen nach 2006/7/EG (§3.2, L315–L338): Binnengewässer (L322–L323) and
// Küstengewässer und Übergangsgewässer (L331–L332) × Intestinale Enterokokken / Escherichia coli × ausgezeichnet / gut /
// ausreichend; "Die Werte in Klammern geben die Art der Perzentil-Bewertung an." (L335). Keyed on prod's combined
// `gewaesserklasse` token (the symbol M205-10 inherits from M205-02) × parameter. The printed Küstengewässer-ausreichend
// cells have NO prod token (gewaesserklasse lists five values) — the rows are seeded under `kueste_ausreichend` so the
// table is complete; the token is m205-E-1 (D-1: enum_values never overwritten here).
// ---------------------------------------------------------------------------
export const TAB2_KLASSEN = ['binnen_ausgezeichnet', 'binnen_gut', 'binnen_ausreichend', 'kueste_ausgezeichnet', 'kueste_gut', 'kueste_ausreichend'] as const;
export const TAB2_PROD_TOKENS = ['binnen_ausgezeichnet', 'binnen_gut', 'binnen_ausreichend', 'kueste_ausgezeichnet', 'kueste_gut'] as const; // capture 2026-09-18
export const TAB2_PARAMETER = [
  { value: 'enterokokken', label_de: 'Intestinale Enterokokken (cfu/100 ml)', methode: 'DIN EN ISO 7899-1 oder DIN EN ISO 7899-2' },
  { value: 'e_coli', label_de: 'Escherichia coli (cfu/100 ml)', methode: 'DIN EN ISO 9308-3 oder DIN EN ISO 9308-1' },
] as const;
/** One printed line = (water type, parameter) → the three category cells "limit (percentile)". */
const TAB2_LINES = [
  { typ: 'binnen', parameter: 'enterokokken', q: 'T2_L322', cells: ['200 (95)', '400 (95)', '330 (90)'] },
  { typ: 'binnen', parameter: 'e_coli', q: 'T2_L323', cells: ['500 (95)', '1.000 (95)', '900 (90)'] },
  { typ: 'kueste', parameter: 'enterokokken', q: 'T2_L331', cells: ['100 (95)', '200 (95)', '185 (90)'] },
  { typ: 'kueste', parameter: 'e_coli', q: 'T2_L332', cells: ['250 (95)', '500 (95)', '500 (90)'] },
] as const;
const KATEGORIEN = ['ausgezeichnet', 'gut', 'ausreichend'] as const;
const parseCell = (c: string): { limit: number; pct: number } => {
  const m = /^([\d.]+) \((\d+)\)$/.exec(c);
  if (!m) throw new Error(`TABELLE2: cell "${c}" is not "limit (pct)"`);
  return { limit: Number(m[1].replace(/\./g, '')), pct: Number(m[2]) };
};
export function tabelle2AsTable(): RegulationTable {
  const rows: RegulationRow[] = [];
  for (const ln of TAB2_LINES) {
    const quote = Q[ln.q];
    const p = TAB2_PARAMETER.find((x) => x.value === ln.parameter)!;
    inSpan(quote, p.methode, `TABELLE2 ${ln.typ}|${ln.parameter}`);
    ln.cells.forEach((c, k) => {
      inSpan(quote, c, `TABELLE2 ${ln.typ}|${ln.parameter}|${KATEGORIEN[k]}`);
      const { limit, pct } = parseCell(c);
      const klasse = `${ln.typ}_${KATEGORIEN[k]}`;
      rows.push({ row_key: `${klasse}|${ln.parameter}`, keys: { gewaesserklasse: klasse, parameter: ln.parameter },
        group_label: ln.typ === 'binnen' ? 'Binnengewässer' : 'Küstengewässer und Übergangsgewässer',
        label_de: `${ln.typ === 'binnen' ? 'Binnengewässer' : 'Küstengewässer'} · ${KATEGORIEN[k]} · ${p.label_de}: ${c}`, order_index: rows.length,
        values: { limit_cfu_100ml: limit, percentile_pct: pct, methode: p.methode }, verbatim_quote: quote });
    });
  }
  return { standard_code: STD, edition: ED, table_code: 'TABELLE2', title_de: 'Mikrobiologische Qualitätsanforderungen an Badegewässer nach der Richtlinie 2006/7/EG (Grenzwert cfu/100 ml, Perzentil in Klammern)', clause_reference: '§3.2, Tab. 2', page_ref: null,
    key_columns: ['gewaesserklasse', 'parameter'],
    value_columns: [num('limit_cfu_100ml', 'cfu/100 ml'), num('percentile_pct', '%'), str('methode')],
    override_policy: 'anhaltswert',
    override_quote: Q.L232, // §2.1 authority sentence
    verification_status: 'md_verified', rows };
}

// ---------------------------------------------------------------------------
