  hg_druck_hpa: string; hg_min: number; hg_max: number; spektrum: string; wellenlaenge_nm: string; wl_min: number; wl_max: number;
  leistung_w: string; p_min: number; p_max: number; leistungsdichte_w_cm: string; pd_min: number; pd_max: number;
